begin;create extension if not exists pgtap with schema extensions;select extensions.no_plan();
insert into auth.users(id)select('4f000000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,6)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at)select id,id,'totp','verified',now(),now()from auth.users where id::text like'4f000000-%';
insert into auth.sessions(id,user_id,factor_id,aal)select id,id,id,'aal2'from auth.users where id::text like'4f000000-%';
insert into public.team_profiles(id,full_name,is_active)select id,'Synthetic event staff',id::text not like'%5'from auth.users where id::text like'4f000000-%';
insert into public.team_role_assignments select('4f000000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from(values(1,'platform_owner'),(2,'content_community_lead'),(3,'operations_lead'),(4,'technical_lead'),(5,'operations_lead'))v(n,code)join public.roles r on r.code=v.code;
create function pg_temp.claims(n int,aal text default'aal2')returns text language sql as $$select json_build_object('sub','4f000000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',aal,'session_id','4f000000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval'1 hour')::bigint)::text$$;
create temp table target(n int primary key,id uuid);grant all on target to authenticated,service_role;
create function pg_temp.t(n int)returns uuid language sql as $$select id from target where target.n=t.n$$;
create function pg_temp.v(n int)returns int language sql as $$select(x->>'version')::int from jsonb_array_elements(public.list_staff_events())x where x->>'id'=pg_temp.t(n)::text$$;
create function pg_temp.rv(n int,e int)returns int language sql as $$select(x->>'version')::int from jsonb_array_elements(public.list_event_registrations(pg_temp.t(e)))x where x->>'id'=pg_temp.t(n)::text$$;
create function pg_temp.h(v text)returns text language sql as $$select encode(sha256(convert_to(v,'UTF8')),'hex')$$;
create function pg_temp.copy(n int)returns jsonb language sql as $$select jsonb_build_object('title','Synthetic event '||n,'description','Local-only fixture, not a real event.','category','Synthetic','posterId',null,'speakers','[]'::jsonb,'schedule','[]'::jsonb,'recap','')$$;
create function pg_temp.ops(n int)returns jsonb language sql as $$select jsonb_build_object('format',case when n=4 then'online'else'physical'end,'startAt',to_char((now()-interval'1 hour')at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'endAt',to_char((now()+interval'2 hours')at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"'),'timeZone','UTC','venue',case when n=4 then''else'Synthetic private test venue'end,'platform',case when n=4 then'Synthetic platform'else''end,'joiningUrl',case when n=4 then'https://video.example.invalid/private-room'else null end,'regOpensAt',null,'regClosesAt',null,'capacity',1,'feeClass',case when n=2 then'paid'else'free'end,'feeXaf',case when n=2 then 10000 else 0 end,'paymentInstructions',case when n=2 then'Synthetic on-site instructions'else''end,'questions','[]'::jsonb)$$;
create function pg_temp.payload(n int,email text)returns jsonb language sql security definer set search_path=''as $$select jsonb_build_object('eventId',e.id,'intakeVersion',e.intake_version,'fullName','Synthetic Participant','email',email,'whatsapp',null,'answers','{}'::jsonb,'consent',true,'consentVersion','event-registration-v1')from business_private.events e where id=pg_temp.t(n)$$;
create function pg_temp.register(n int,k text,email text,p_invite uuid default null,p_access text default null)returns void language sql as $$select public.submit_event_registration(pg_temp.payload(n,email),'BWE-'||md5(k),pg_temp.h('identity:'||n||email),pg_temp.h('key:'||k),pg_temp.h(pg_temp.payload(n,email)::text),pg_temp.h('receipt:'||k),pg_temp.h('events-global'),pg_temp.h('email:'||email),pg_temp.h('event:'||n),p_invite,p_access)$$;
select extensions.is((select count(*)from public.permissions),37::bigint,'two event permissions added');select extensions.is((select count(*)from public.role_permissions),73::bigint,'four scoped event mappings');
select extensions.ok(not has_table_privilege('anon','business_private.events','select'),'anonymous cannot read private events');select extensions.ok(not has_table_privilege('authenticated','business_private.event_registrations','SELECT,INSERT,UPDATE,DELETE'),'direct attendee CRUD denied');
select extensions.ok(not has_function_privilege('anon','public.claim_private_event(text,text,text,text,text,text)','execute'),'private claims require fixed ingress');select extensions.ok(not has_function_privilege('service_role','public.check_in_event_ticket(uuid,text,text)','execute'),'ingress cannot impersonate staff at check-in');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3,'aal1'),true);
select extensions.throws_ok($$select public.list_staff_events()$$,'42501',null,'AAL1 event operations denied');select extensions.throws_ok($$select public.list_event_attendance(null)$$,'42501',null,'AAL1 attendance denied');
select set_config('request.jwt.claims',pg_temp.claims(6),true);select extensions.throws_ok($$select public.list_staff_events(true)$$,'42501',null,'unassigned AAL2 denied');
select set_config('request.jwt.claims',pg_temp.claims(5),true);select extensions.throws_ok($$select public.list_staff_events()$$,'42501',null,'inactive Operations denied');
select set_config('request.jwt.claims',pg_temp.claims(4),true);select extensions.throws_ok($$select public.list_staff_events(true)$$,'42501',null,'Technology cannot scan');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
insert into target select n,public.save_event_copy(null,0,'synthetic-event-'||n,pg_temp.copy(n))from generate_series(1,4)n;
select extensions.is(public.get_public_event('synthetic-event-1'),null::jsonb,'draft hidden');
select extensions.throws_ok($$select public.publish_event(pg_temp.t(1),pg_temp.v(1),true)$$,'22023',null,'cannot publish without approved logistics');
select extensions.throws_ok($$select public.configure_event(pg_temp.t(1),pg_temp.v(1),pg_temp.ops(1),'public',false,'planned',true)$$,'42501',null,'Content cannot change private visibility or operations');
select extensions.throws_ok($$select public.list_event_registrations(pg_temp.t(1))$$,'42501',null,'Content cannot read attendees');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select public.configure_event(pg_temp.t(n),pg_temp.v(n),pg_temp.ops(n),case when n=1 then'private'else'public'end,false,'planned',true)from generate_series(1,4)n;
select set_config('request.jwt.claims',pg_temp.claims(2),true);select public.publish_event(pg_temp.t(n),pg_temp.v(n),true)from generate_series(1,4)n;
select extensions.is(jsonb_array_length(public.list_public_events()),3,'private published event excluded from discovery');select extensions.is(public.get_public_event('synthetic-event-1'),null::jsonb,'private slug lookup reveals nothing');
select extensions.ok(not(public.get_public_event('synthetic-event-4')->'operations')?'joiningUrl','public online page omits meeting link');select extensions.ok((public.list_staff_events()->0->'operations')='null'::jsonb,'Content projection omits operational confidential fields');
select set_config('request.jwt.claims',pg_temp.claims(3),true);select public.configure_event(pg_temp.t(n),pg_temp.v(n),pg_temp.ops(n),case when n=1 then'private'else'public'end,true,'planned',true)from generate_series(1,4)n;
select extensions.throws_ok($$select public.configure_event(pg_temp.t(2),pg_temp.v(2),pg_temp.ops(2),'public',true,'completed',true)$$,'22023',null,'completion before end denied');
insert into target values(30,'4f000000-0000-4000-8000-000000000030');
select public.create_event_invite(pg_temp.t(30),pg_temp.t(1),pg_temp.v(1),'approved@example.invalid',pg_temp.h('invite'),pg_temp.h('independent-code'),now()+interval'1 hour','Synthetic independently verified mailbox');
select extensions.throws_ok($$select public.configure_event(pg_temp.t(1),pg_temp.v(1),pg_temp.ops(1),'public',true,'planned',true)$$,'22023',null,'private visibility locks after invitation');
set local role service_role;
select extensions.is(public.claim_private_event(pg_temp.h('invite'),pg_temp.h('wrong-code'),'approved@example.invalid',pg_temp.h('guest'),pg_temp.h('claim-global'),pg_temp.h('claim-invite')),null::uuid,'forwarded link without independent code does not work');
select extensions.is(public.claim_private_event(pg_temp.h('invite'),pg_temp.h('independent-code'),'other@example.invalid',pg_temp.h('guest'),pg_temp.h('claim-global'),pg_temp.h('claim-invite')),null::uuid,'wrong recipient cannot claim invitation');
select extensions.is(public.claim_private_event(pg_temp.h('invite'),pg_temp.h('independent-code'),'approved@example.invalid',pg_temp.h('guest'),pg_temp.h('claim-global'),pg_temp.h('claim-invite')),pg_temp.t(30),'independent eligibility proofs grant scoped access');
select extensions.is(public.read_private_event(pg_temp.t(30),pg_temp.h('guest'))->>'title','Synthetic event 1','verified guest sees only scoped event');
select extensions.throws_ok($$select public.read_private_event(pg_temp.t(30),pg_temp.h('bad-guest'))$$,'42501',null,'bad guest cookie fails closed');
select extensions.throws_ok($$select pg_temp.register(1,'private-forged','forged@example.invalid',pg_temp.t(30),pg_temp.h('guest'))$$,'42501',null,'verified guest cannot register a different email');
select extensions.lives_ok($$select pg_temp.register(1,'private','approved@example.invalid',pg_temp.t(30),pg_temp.h('guest'))$$,'verified private registration succeeds');
select extensions.lives_ok($$select pg_temp.register(2,'paid-a','paid-a@example.invalid')$$,'public paid registration reserves a place without payment');
select extensions.lives_ok($$select pg_temp.register(2,'paid-a','paid-a@example.invalid')$$,'idempotent registration retry');
select extensions.lives_ok($$select pg_temp.register(2,'paid-duplicate','paid-a@example.invalid')$$,'duplicate never allocates another place');
select extensions.lives_ok($$select pg_temp.register(2,'paid-b','paid-b@example.invalid')$$,'full event creates waiting-list record');
select extensions.lives_ok($$select pg_temp.register(3,'free-a','free-a@example.invalid')$$,'free public registration');select extensions.lives_ok($$select pg_temp.register(3,'free-b','free-b@example.invalid')$$,'free waiting list');select extensions.lives_ok($$select pg_temp.register(4,'online','online@example.invalid')$$,'online account-free registration');
select extensions.throws_ok($$select public.read_event_receipt(pg_temp.h('receipt:paid-a'),null,null,null,false)$$,'42501',null,'receipt alone does not expose membership or attendee details');
reset role;
select extensions.is((select attempts from business_private.event_buckets where scope='claim_invite'and key_hash=decode(pg_temp.h('claim-invite'),'hex')),3,'failed claim attempts consume durable quota');
insert into target select 10,id from business_private.event_registrations where reference='BWE-'||md5('private');insert into target select 11,id from business_private.event_registrations where reference='BWE-'||md5('paid-a');insert into target select 12,id from business_private.event_registrations where reference='BWE-'||md5('paid-b');insert into target select 13,id from business_private.event_registrations where reference='BWE-'||md5('free-a');insert into target select 14,id from business_private.event_registrations where reference='BWE-'||md5('free-b');insert into target select 15,id from business_private.event_registrations where reference='BWE-'||md5('online');
select extensions.is((select count(*)from business_private.event_registrations where event_id=pg_temp.t(2)and status='confirmed'),1::bigint,'one confirmed paid place');select extensions.is((select count(*)from business_private.event_registrations where event_id=pg_temp.t(2)and status='waitlisted'),1::bigint,'one paid waiting-list entry');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.change_event_registration(pg_temp.t(12),pg_temp.rv(12,2),'promote','Overbook attempt')$$,'22023',null,'promotion cannot overbook');
select extensions.throws_ok($$select public.issue_event_ticket(pg_temp.t(11),pg_temp.rv(11,2),'4f000000-0000-4000-8000-000000000021','BWT-'||md5('paid-ticket'),pg_temp.h('paid-qr'),false,'')$$,'42501',null,'unpaid registration cannot obtain valid ticket');
select extensions.throws_ok($$select public.record_event_payment(pg_temp.t(11),pg_temp.rv(11,2),true,1,'Wrong amount')$$,'22023',null,'payment evidence must match exact approved fee');
select public.record_event_payment(pg_temp.t(11),pg_temp.rv(11,2),true,10000,'Synthetic verified physical payment');
select public.authorize_event_portal(pg_temp.t(11),pg_temp.rv(11,2),pg_temp.h('participant-code'),'Synthetic independent recipient verification');
select extensions.lives_ok($$select public.issue_event_ticket(pg_temp.t(11),pg_temp.rv(11,2),'4f000000-0000-4000-8000-000000000021','BWT-'||md5('paid-ticket'),pg_temp.h('paid-qr'),false,'')$$,'paid-cleared physical ticket issued');
select extensions.is(public.issue_event_ticket(pg_temp.t(11),1,'4f000000-0000-4000-8000-000000000099','BWT-'||md5('duplicate-ticket'),pg_temp.h('duplicate-qr'),false,'')->>'id','4f000000-0000-4000-8000-000000000021','repeated issue returns existing ticket without duplicate creation');
set local role service_role;
select extensions.is(public.read_event_receipt(pg_temp.h('receipt:paid-a'),pg_temp.h('participant-code'),null,null,false)->>'participantName','Synthetic Participant','verified recipient may view own registration');
select extensions.ok((public.read_event_receipt(pg_temp.h('receipt:paid-a'),pg_temp.h('participant-code'),null,null,false)->>'ticketAvailable')::boolean,'eligible private ticket available');
select extensions.throws_ok($$select public.read_event_receipt(pg_temp.h('receipt:paid-a'),pg_temp.h('wrong-participant-code'),null,null,true)$$,'42501',null,'receipt plus wrong code cannot download PDF data');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select public.record_event_payment(pg_temp.t(11),pg_temp.rv(11,2),false,10000,'Synthetic clearance revocation');
select extensions.throws_ok($$select public.verify_event_ticket(pg_temp.t(2),pg_temp.h('paid-qr'),null)$$,'42501',null,'payment revocation blocks issued QR immediately');
select public.record_event_payment(pg_temp.t(11),pg_temp.rv(11,2),true,10000,'Synthetic verified again');
select extensions.throws_ok($$select public.verify_event_ticket(pg_temp.t(3),pg_temp.h('paid-qr'),null)$$,'42501',null,'wrong event cannot resolve attendee data');
select extensions.throws_ok($$select public.verify_event_ticket(pg_temp.t(2),pg_temp.h('random'),null)$$,'42501',null,'invalid QR denied');
select extensions.is(public.verify_event_ticket(pg_temp.t(2),pg_temp.h('paid-qr'),null)->>'status','eligible','valid QR verifies without attendance');
reset role;select extensions.is((select count(*)from business_private.event_attendance),0::bigint,'verify does not check participant in');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.is(public.check_in_event_ticket(pg_temp.t(2),pg_temp.h('paid-qr'),null)->>'status','checked_in','explicit check-in succeeds');
select extensions.is(public.check_in_event_ticket(pg_temp.t(2),null,'BWT-'||md5('paid-ticket'))->>'status','already_checked_in','manual reference detects duplicate');
select extensions.throws_ok($$select public.change_event_registration(pg_temp.t(11),pg_temp.rv(11,2),'cancel','Unsafe capacity release')$$,'22023',null,'cannot free seat for attendee already present');
select extensions.throws_ok($$select public.issue_event_ticket(pg_temp.t(11),pg_temp.rv(11,2),'4f000000-0000-4000-8000-000000000022','BWT-'||md5('post-entry'),pg_temp.h('post-entry'),true,'Post-entry')$$,'22023',null,'cannot reissue after attendance');
select public.issue_event_ticket(pg_temp.t(10),pg_temp.rv(10,1),'4f000000-0000-4000-8000-000000000023','BWT-'||md5('private-ticket1'),pg_temp.h('private-qr1'),false,'');
select public.issue_event_ticket(pg_temp.t(10),pg_temp.rv(10,1),'4f000000-0000-4000-8000-000000000024','BWT-'||md5('private-ticket2'),pg_temp.h('private-qr2'),true,'Explicit synthetic replacement');
select extensions.throws_ok($$select public.verify_event_ticket(pg_temp.t(1),pg_temp.h('private-qr1'),null)$$,'42501',null,'reissue revokes old QR');select extensions.is(public.verify_event_ticket(pg_temp.t(1),pg_temp.h('private-qr2'),null)->>'status','eligible','replacement QR eligible');
select public.revoke_event_invite(pg_temp.t(30),1);
select extensions.throws_ok($$select public.verify_event_ticket(pg_temp.t(1),pg_temp.h('private-qr2'),null)$$,'42501',null,'private eligibility revocation blocks replacement ticket');
set local role service_role;select extensions.throws_ok($$select public.read_private_event(pg_temp.t(30),pg_temp.h('guest'))$$,'42501',null,'revocation invalidates cached guest session');select extensions.throws_ok($$select public.read_event_receipt(pg_temp.h('receipt:private'),null,pg_temp.t(30),pg_temp.h('guest'),false)$$,'42501',null,'revoked private recipient cannot use receipt');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(3),true);
select public.change_event_registration(pg_temp.t(13),pg_temp.rv(13,3),'cancel','Synthetic verified cancellation');
select extensions.is((select x->>'status' from jsonb_array_elements(public.list_event_registrations(pg_temp.t(3)))x where x->>'id'=pg_temp.t(14)::text),'waitlisted','cancellation does not silently auto-promote');select public.change_event_registration(pg_temp.t(14),pg_temp.rv(14,3),'promote','Synthetic reviewed manual promotion');
select extensions.throws_ok($$select public.issue_event_ticket(pg_temp.t(15),pg_temp.rv(15,4),'4f000000-0000-4000-8000-000000000025','BWT-'||md5('online'),pg_temp.h('online'),false,'')$$,'42501',null,'online-only registration has no physical ticket');
select public.authorize_event_portal(pg_temp.t(15),pg_temp.rv(15,4),pg_temp.h('online-code'),'Synthetic recipient verification');
set local role service_role;select extensions.is(public.read_event_receipt(pg_temp.h('receipt:online'),pg_temp.h('online-code'),null,null,false)->>'joiningUrl','https://video.example.invalid/private-room','restricted online link released only to verified confirmed recipient');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(2),true);select extensions.throws_ok($$select public.list_event_attendance(pg_temp.t(2))$$,'42501',null,'Content cannot inspect attendance');
reset role;select extensions.is((select count(*)from business_private.event_attendance where event_id=pg_temp.t(2)),1::bigint,'one atomic attendance record');select extensions.is((select count(*)from public.audit_logs where action='event.checked_in'and resource_id=pg_temp.t(11)::text),1::bigint,'duplicate scans do not duplicate audit');select extensions.is((select count(*)from business_private.event_tickets where registration_id=pg_temp.t(10)),2::bigint,'ticket reissue history retained');
select * from extensions.finish();rollback;
